mapper.select:
        select  t.card_num,t.card_num cardNum,t.acyc_id,t.acyc_id acycId,t.person_id,t.person_id personId,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id communityId 
from access_control_yite_card t 
where 1 =1 

   and t.card_num= #{cardNum}


   and t.acyc_id= #{acycId}


   and t.person_id= #{personId}


   and t.status_cd= #{statusCd}


   and t.community_id= #{communityId}

order by t.create_time desc

   limit #{page}, #{row}

